globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-24 05:01:09 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"脆弱性の「CVSS 9.8」って結局なに？CVSSの読み方をちゃんと理解する - Qiita","url":"https://qiita.com/heki-dm/items/77ecaacd592d1c4459df","source":"Hatena","published_at":"2026-11-22 18:00","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CVSSスコアだけで判断しない、脆弱性評価の正しい読み方","summary":"脆弱性の深刻度を示すCVSSスコアについて、数値の大きさだけでなくベクタ文字列を読み解く重要性を解説。CVSSは「深刻度」を測るものであり「リスク」ではないという前提のもと、環境に応じた優先順位付けの考え方を提示している。\n\nv3.1とv4.0の違いや、Baseスコアに含まれない情報の重要性に触れ、実際の脆弱性対応において何を基準に判断すべきかを具体的に指南。セキュリティ担当者にとって、機械的なスコア依存から脱却するための指針となる。","importance":9},{"title":"NVIDIA Board Reinstates Jensen Huang as President, CEO and Board Director | NVIDIA Newsroom","url":"https://nvidianews.nvidia.com/news/nvidia-board-reinstates-jensen-huang-as-president-ceo-and-board-director","source":"Hatena","published_at":"2026-11-23 23:09","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"NVIDIA (NASDAQ: NVDA) today announced that effective immediately, J…","summary":"NVIDIA (NASDAQ: NVDA) today announced that effective immediately, Jensen Huang has been reinstated as President and Chief Executive Officer and as a member of the Board.\n\nThe Board of Directors voted unanimously to reinstate Mr.Huang following a series of discussions and meetings with Mr.\n\nHuang, after which the Board was satisfied with respect to Mr.Huang’s candor and ability to lead NVIDIA.","importance":5},{"title":"MacMimic 解説：G1 の全身動作追従の学習を MacBook で約 22 分にした BlinkMimic の移植","url":"https://zenn.dev/atokiwa/articles/f0f9dc6d4930ee","source":"Zenn","published_at":"2026-11-22 21:12","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AppleシリコンMacでヒューマノイドの動作学習を高速化するMacMimic","summary":"NVIDIA GPUなしのMacで、Unitree G1などのヒューマノイドの全身動作追従学習を高速に行うための「MacMimic」の解説。SuperMimicの学習ループをベースに、シミュレーションをCPU、ニューラルネット学習をGPUで並列処理する手法を採用している。\n\nAppleシリコンの共有メモリ構造を活かし、データコピーを排除することで学習効率を最大化。M5チップ搭載のMacBookで約30分程度で学習を完了させるなど、個人環境でのロボティクス学習のハードルを大幅に下げた点が注目される。","importance":8},{"title":"ジェンスン・フアン氏、11日間の不在の後、NVIDIAのCEOに返り咲き | テクノエッジ TechnoEdge","url":"https://www.techno-edge.net/article/2026/11/23/5793.html","source":"Hatena","published_at":"2026-11-24 00:05","genre":"other","genre_label":"総合・その他IT","headline":"NVIDIAの創業者であるジェンスン・フアン氏が、社長兼CEO（代表取締役）として復帰しました。","summary":"NVIDIAの創業者であるジェンスン・フアン氏が、社長兼CEO（代表取締役）として復帰しました。NVIDIAが2026年11月23日（米国時間）、取締役会が全会一致で決定したとして 発表 。\n\n取締役会はフアン氏との協議・面談を経て、同氏の誠実さとNVIDIAを率いる能力に納得したとして復帰を承認。米国の国家安全保障上のリスクをもたらさないとの判断を、米国政府からも得ているそうです。\n\n同社は11月12日（米国時間）に、フアン氏の退任を 発表 していましたが、わずか11日で復帰したことになります。フアン氏はXへの投稿で、CEO復帰に意欲を見せていました。\n\n暫定CEOを務めていたコレット・クレス氏は最高財務責任者（CFO）としての職務を継続。なお、外国の情報工作の標的になったとする件については、独立系法律顧問の支援のもとで調査を続けており、フアン氏も調査を全面的に支持し、協力していく姿勢を示しています。","importance":5},{"title":"goroutine（ゴルーチン）はgoを付けただけでは終わらない","url":"https://zenn.dev/mkt_engr/articles/go-goroutine-3-phases","source":"Zenn","published_at":"2026-11-22 20:58","genre":"web","genre_label":"Web開発・言語","headline":"Goのgoroutineを安全に管理する3つのステップ","summary":"Go言語の並行処理において、goroutineを単に起動するだけでなく、終了待機、同時実行数制御、安全な停止（Graceful Shutdown）を実現するための実装ガイド。sync.WaitGroupやchannel、contextを用いた管理手法を段階的に解説している。\n\nプログラムの予期せぬ終了を防ぎ、リソースを適切に解放するためのベストプラクティスを網羅。並行処理を多用するアプリケーションにおいて、堅牢な設計を維持するための必読の知識となっている。","importance":8},{"title":"「Microsoft To Do」、2027年6月にアプリ提供終了　法人向けは「Planner」へ移行、個人向けは代替なし","url":"https://www.itmedia.co.jp/news/article/2611/23/2000003395/","source":"Hatena","published_at":"2026-11-23 12:27","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"一方、「Microsoft 365 Personal」や「Microsoft 365 Family」を含む個人アカウントでは、To D…","summary":"一方、「Microsoft 365 Personal」や「Microsoft 365 Family」を含む個人アカウントでは、To Doアプリが終了してもPlannerは使えない。Microsoftはこうしたユーザーに、残したいタスクやリストを決めて、ほかのタスク管理アプリを選ぶよう勧めている。\n\nTo Doアプリにあるタスクやリストは、Plannerに自動では移らない。Microsoftは、タスク管理アプリ「Microsoft To Do」の全プラットフォーム向けアプリを2027年6月30日に提供終了すると発表した。\n\n職場・学校アカウント向けには「Microsoft Planner」を後継として案内するが、個人アカウントでは利用できず、代替アプリへの移行を勧めている。既存データは自動移行されない。\n\n米Microsoftは11月18日（現地時間）、タスク管理アプリ「Microsoft To Do」（以下「To Doアプリ」）の提供を終了すると公式サポートページで発表した。","importance":5},{"title":"Claude Code を安全に「自走」させるなら、もう Docker Sandboxes 一択でよくない？と思った話。｜YamaC / ﾔﾏｼｰ","url":"https://note.com/yamac_/n/n198bdc344c64","source":"Hatena","published_at":"2026-11-22 19:08","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AIエージェントの安全な自走環境にDocker Sandboxesが最適","summary":"Claude CodeなどのAIコーディングエージェントを安全に運用するための隔離環境として、Docker Sandboxes（sbx）の活用を推奨する解説。MicroVMによるカーネルレベルの隔離と、デフォルト拒否の通信制限により、ホスト環境へのリスクを最小化できる。\n\n従来のコンテナよりも強力なセキュリティモデルを持ち、商用利用も可能なため、企業環境でのAIエージェント導入における現実的な解として注目される。Windows環境での導入手順や、セキュリティ設計のポイントがまとめられている。","importance":8},{"title":"Lean で手続き的プログラム の証明が書けるようになった","url":"https://speakerdeck.com/inoueasei/slide-aa115490-ea99-4286-9de2-40794f4e861f","source":"Hatena","published_at":"2026-11-23 17:38","genre":"other","genre_label":"総合・その他IT","headline":"Leanで、最近手続き的プログラムの形式検証がDafnyのようにできるようになりました。","summary":"Leanで、最近手続き的プログラムの形式検証がDafnyのようにできるようになりました。それについて軽く紹介します Lean で手続き的プログラム の証明が書けるようになった TPP2026 2026.11.16-17 井上亜星 Lean で手続き的プログラム の証明が書けるようになった TPP2026 2026.11.16-17 井上亜星 Lean 知ってますか • 定理証明支援系でありつつ、プログラミング言語でもある • Lean でプログラムを書いて Lean で検証できる • プログラム検証と相性良いのでは？\n\n（私の意見） Lean で手続き的プログラム TPP2026 Lean 知ってますか • 定理証明支援系でありつつ、プログラミング言語でもある • Lean でプログラムを書いて Lean で検証できる • プログラム検証と言えば やっぱ reverse ですよね！","importance":5},{"title":"ソフトウェアファクトリーは不要なのか？1.5倍の中身はファクトリー以外だった","url":"https://zenn.dev/z_maruhira/articles/software-factory-needed","source":"Zenn","published_at":"2026-11-22 21:10","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"ソフトウェアファクトリー導入で生産性が1.5倍に向上した理由","summary":"AIエージェントを活用した「ソフトウェアファクトリー」を構築し、個人のストーリーポイント生産性を1.5倍に向上させた実践記録。単にAIがコードを書くこと以上に、開発プロセスの標準化やチームの少人数化、並列作業の習慣化が寄与したと分析している。\n\n一方で、レビュー負荷の増大やインクリメンタルな開発における依存関係がボトルネックとなり、生産性の伸びが頭打ちになる課題も指摘。AI時代の開発組織において、レビューのあり方やタスクの疎結合化が重要であることを示唆している。","importance":7},{"title":"【TLA+】AIにテストケースを書かせるな。ルールを書け","url":"https://zenn.dev/karamage/articles/73027ee36796dc","source":"Zenn","published_at":"2026-11-21 11:12","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代のテストは「ケース」ではなく「守るべきルール」を書く","summary":"AIがテストコードまで生成する時代において、人間がテストケースを考えることの限界を指摘し、TLA+やQuintを用いた「ルールベースの形式検証」への転換を提唱する記事。AIによる「自作自演の満点」を回避し、システムの不変条件を保証する手法を解説している。\n\nテストオラクル問題に対する現実的な解として、設計段階でのルール定義の重要性を強調。AIに依存しすぎない、堅牢なソフトウェア設計のためのパラダイムシフトを促す内容である。","importance":9},{"title":"Next.jsのストリーミングはLambda Web Functionsで動くか","url":"https://zenn.dev/ryota_09/articles/nextjs-suspense-streaming-lambda-web-functions","source":"Zenn","published_at":"2026-11-22 11:30","genre":"web","genre_label":"Web開発・言語","headline":"Lambda Web FunctionsでNext.jsのストリーミングは動くのか","summary":"AWS Lambdaの新しい実行形態「Lambda Web Functions」上で、Next.jsのSuspenseストリーミングが正しく動作するかを実測検証したレポート。結果として、追加設定なしでVercelと同等の段階表示が実現できることを確認した。\n\nコールドスタート以外ではVercelとの性能差はほとんどなく、Lambda Web Adapterよりも効率的な運用が可能。Next.jsのSSRストリーミングをAWS上で活用したいエンジニアにとって、非常に価値の高い検証結果である。","importance":7},{"title":"MPLUS_FONTS/fonts/MPLUS3 at master · coz-m/MPLUS_FONTS","url":"https://github.com/coz-m/MPLUS_FONTS/tree/master/fonts/MPLUS3","source":"Hatena","published_at":"2026-11-23 16:00","genre":"other","genre_label":"総合・その他IT","headline":"You signed in with another tab or window.","summary":"You signed in with another tab or window.Reload to refresh your session.\n\nYou signed out in another tab or window.You switched accounts on another tab or window.\n\nDismiss alert M+ FONTS.Contribute to coz-m/MPLUS_FONTS development by creating an account on GitHub.","importance":5},{"title":"無料でMacのアプリのウィンドウをiPhoneやiPadからリアルタイムに操作できる「Sill」、オープンソースで中継サーバー不要","url":"https://gigazine.net/news/20261123-sill/","source":"Hatena","published_at":"2026-11-23 12:11","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Macで作業していると手元のiPhoneやiPadから特定のアプリケーションだけを操作したいことがあります。","summary":"回線や台数を整理し見直せる部分は全て見直しましたが、やはりまだ危険水域です。・ これまでGIGAZINEを支援してくれたメンバーのリスト Macで作業していると手元のiPhoneやiPadから特定のアプリケーションだけを操作したいことがあります。\n\nそこでMacのウィンドウをリアルタイムで転送し、タッチ・キーボード・トラックパッド・Apple Pencilなどで操作できるようにしたサーバー不要の無料のオープンソースアプリが「 Sill 」です。Sill: windows from your Mac on your iPhone and iPad https://getsill.app/ GitHub - Saffsanity/sill: Any window from your Mac, live on your iPhone or iPad. https://github.com/Saffsanity/sill ◆Sillでできること SillはMacで動作しているデスクトップ全体に加えてアプリのウィンドウ単位で映像を転送できるのが特徴です。","importance":5},{"title":"CloudWatch Agentがjournaldを直接読めるようになったので、AL2023で試した","url":"https://zenn.dev/smori/articles/cloudwatch-logs-journald-collection","source":"Zenn","published_at":"2026-11-22 21:07","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CloudWatch Agentがjournaldを直接収集可能に、rsyslogが不要へ","summary":"CloudWatch Agentのアップデートにより、rsyslogを介さずjournaldのログを直接収集可能になった。これにより、Amazon Linux 2023などのモダンな環境で、ログ収集のための追加設定やファイル管理が大幅に簡素化される。\n\n設定ファイルでunitsやpriorityを指定することで、必要なログのみを構造化されたJSON形式でCloudWatch Logsへ転送できる。rsyslogの運用負荷を削減し、システムログの管理を効率化する実用的な改善である。","importance":7},{"title":"氷河期オタクエンジニアおじさん、底辺文化地域で暮らす。","url":"https://anond.hatelabo.jp/20261123174519","source":"Hatena","published_at":"2026-11-23 17:55","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"地域については「電車で東京に通勤通学は可能な範囲」とだけ言っておく たぶんそこを知ってる人たちなら言わなくとも「ああ、あそこあたりか……","summary":"地域 については「 電車 で 東京 に 通勤 通学は 可能 な 範囲 」とだけ言っておく たぶんそこを知ってる人たちなら言わなくとも「ああ、あそこあたりか…」)とわかって しま うかもしれないけど 当方 、 IT 業界 の 底辺 を 彷徨 い続けてきた 就職氷河期 世代 の エンジニア おじさん なのだ が、 コロナ 禍の頃に 転職 して、そこ から フル リモート だったので、どうせ あん まり 外出ないし思 いっき り 家賃 安いところに 引っ越し ちゃお うと思い、 友人の伝手をたどってその 地域 の 一角 の マンション へと 引っ越し て、ついこの間まで延べ5年ほど 暮らし て いたこ とがあったけど、いろいろ 文化 が違っていて 面白 かったので、書く。\n\nいっぱい書きたいこともあるが、長くなるので、ヤック・デ・ カルチャー なところだけ箇条書きと軽い補足にとどめておこうと思う。普通に 暮らし ていて 文化 が違うと思った日々の細々 ・ 喫煙 率がすごい高い。","importance":5},{"title":"NVIDIAグラボの「SSD無限酷使」現象、修正パッチを適用しても直らないとの報告。ちょっと改善するも、まだ書き込みまくる - AUTOMATON","url":"https://automaton-media.com/articles/newsjp/20261123-480470/","source":"Hatena","published_at":"2026-11-23 15:49","genre":"other","genre_label":"総合・その他IT","headline":"NVIDIAグラボの「SSD無限酷使」現象、修正パッチを適用しても直らないとの報告。","summary":"NVIDIAグラボの「SSD無限酷使」現象、修正パッチを適用しても直らないとの報告。ちょっと改善するも、まだ書き込みまくる 「GeForce Game Ready Driver」のホットフィックス621.35配信後も、PCを操作していない間にもSSDへの大量の書き込みがおこなわれる不具合が継続しているようだ。\n\n「GeForce Game Ready Driver」のホットフィックス621.35配信後も、PCを操作していない間にもSSDへの大量の書き込みがおこなわれる不具合が継続しているようだ。","importance":5},{"title":"Orca Botsが良さそう、何ができるのか","url":"https://zenn.dev/kg_motors_mibot/articles/orca-bot-intro","source":"Zenn","published_at":"2026-11-22 00:14","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントの常設・自動化を実現する「Orca Bots」の可能性","summary":"AI IDE「Orca」に導入された「Orca Bots」の紹介。Claude Code等のAIエージェントを役割や記憶を持ったBotとして常設し、SlackやGitHub等のイベントを起点に自律的なタスク実行を可能にする仕組みである。\n\n単なるAI呼び出しを超え、日常業務のワークフローにAIを組み込み、人間への引き継ぎまでを一貫して扱える点が特徴。AIエージェントによる開発自動化を次のフェーズへ進めるための、実用的なツールとして期待される。","importance":8},{"title":"GitHub - AFK-surf/xnulinux: XNU as a loadable kernel module inside Linux (macOS personality for arm64 Linux)","url":"https://github.com/AFK-surf/xnulinux","source":"Hatena","published_at":"2026-11-23 21:27","genre":"web","genre_label":"Web開発・言語","headline":"Run macOS userspace on Linux by loading the macOS kernel into it. x…","summary":"Run macOS userspace on Linux by loading the macOS kernel into it. xnulinux builds XNU, the open-source kernel of macOS, from Apple's published sources and runs it as a loadable kernel module (xnu.ko) inside an unmodified arm64 Linux kernel.","importance":5},{"title":"通信が切れて作られなかった振り返りを、会話ごとの ID で送り直す――Flutter と Cloud Functions の4つの穴","url":"https://zenn.dev/wa_rp_studio/articles/flutter-firebase-feedback-retry","source":"Zenn","published_at":"2026-11-23 12:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Android の英会話アプリ TalkFlow（Flutter と Firebase）で、会話を終えたときに Cloud Funct…","summary":"Android の英会話アプリ TalkFlow（Flutter と Firebase）で、会話を終えたときに Cloud Functions で作る「振り返り」が、通信が切れていると作られないまま消えていました。振り返りは、その会話の英語の添削と、苦手な単語の単語帳への追加です。\n\n送る前に端末に残し、会話ごとの ID で送り直す形に直しました。形はよくあるものですが、送り直しの回数の数え方や、Android の「表に戻った」の拾い方で、いくつか穴がありました。\n\nアプリは会話を終えると、呼び出し型の関数 generateFeedback に会話の中身を送り、返事を見ていませんでした。通信が切れていると呼び出しは失敗し、その会話は学習履歴に出ないままでした。\n\n会話を終えたときに会話ごとの ID を作り、依頼（会話の中身と ID）を shared_preferences に残してから送ります。直した最初の版では、失敗してから残していたので、返事を待つ間にアプリを閉じられると依頼が消えていました。","importance":5},{"title":"マーケティング酔い","url":"https://zenn.dev/piroyoung/articles/9bad6963f2b39e","source":"Zenn","published_at":"2026-11-22 18:53","genre":"other","genre_label":"総合・その他IT","headline":"技術の本質を覆い隠す「マーケティング酔い」への警鐘","summary":"医薬品やIT製品において、本質的には同じ機能を持つ製品が過剰なマーケティングメッセージで差別化され、消費者が正しい判断を下せなくなる現象を「マーケティング酔い」と定義したエッセイ。データベース製品を例に、技術的特性よりもパッケージングが優先される現状を批判している。\n\n技術者として、煌びやかな宣伝ではなく、中身が正確に理解できる誠実な情報提供の重要性を説く。ITソリューションの選定において、技術的な「有効成分」を明示することの価値を再考させる内容。","importance":5},{"title":"Windows Server 2016 からの Active Directory 移行、アップグレードにあたっての考慮事項","url":"https://jpwinsup.github.io/blog/2026/08/05/ActiveDirectory/PromotionAndDemotion/windows-server-2016-ad-migration-considerations/?utm_source=chatgpt.com","source":"Hatena","published_at":"2026-11-23 20:49","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"本記事はマイクロソフト社員によって公開されております。","summary":"本記事はマイクロソフト社員によって公開されております。(作成にあたり Copilot の力を借りています) こんにちは。\n\nWindows Commercial Support Directory Services チームです。Windows Server 2016 は 2027 年 1 月 12 日にサポート終了を迎えます。\n\n本記事は、Windows Server 2016 で稼働するドメイン コントローラーを Windows Server 2022 または Windows Server 2025 へ移行、アップグレードする際の主な考慮事項や手順をまとめたものです。ドメイン コントローラーの移行にあたっては、移行先 OS の更新プログラムで有効になる脆弱性対応を確認し、移行元 OS にも同じ脆弱性へ対応する更新プログラムを適用しておくことが重要です。\n\n移行元と移行先で脆弱性対応の状態をそろえることで、新旧のドメイン コントローラーを並行稼働させる期間の認証動作の互換性を確保します。","importance":5},{"title":"優秀な人が小さくまとまる現象 - pospomeのプログラミング日記","url":"https://www.pospome.work/entry/2026/11/23/125036","source":"Hatena","published_at":"2026-11-23 13:14","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"株式会社カミナシで VPoE を務めている pospome です。","summary":"株式会社カミナシで VPoE を務めている pospome です。(´・ω・`) エンジニアに限らずですが、優秀な人ほど物事を進める際のリスクを認識できるようになります。\n\n経験を積むと「これをやるとこうなりそうだな」という予測が立つようになるので、それ自体はとても良いことです。ただ、過度にリスクを避けた結果、できることしかやらない人になってしまうことがあります。\n\n失敗しないので一見優秀に見えるんですけど、失敗の経験を積めないので成長が限定されてしまったり、大きな成果を出すのが難しくなってしまったりするわけです。今回はこの \"優秀な人が小さくまとまる現象\" について書いてみようと思います。\n\n優秀だけど伸びない人がいる 優秀な人はみんな大きい成功と大きい失敗をしていると思う リスクを取ってリターンを得る とりあえずやってみるマインド 社会人経験が長くなってくると、多くのエンジニアと接することになります。そうすると、長い期間で見たときに「この人優秀なんだけど伸びないんだよなー」と思う人がいたりします。","importance":5},{"title":"寝てる間に自動で動くAIエージェントを誰でも作れる：10分でわかる pstack 実践ガイド","url":"https://zenn.dev/canly/articles/ca6875cd79539f","source":"Zenn","published_at":"2026-11-20 18:04","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeとpstackで寝ている間にPRを自動生成する実践ガイド","summary":"Cursor公式のスキル集「pstack」をClaude Codeに導入し、設計から実装、テストまでを人手なしで完走させた実践レポート。AIがコードを書きすぎる問題を回避し、質の高いコードを生成するためのプレイブック活用術を解説している。\n\n指示の組み立て方や、実行ログに基づいた自動化のプロセスを詳細に記録。AIエージェントを自律的に働かせるための具体的な手法として、開発効率を劇的に向上させる可能性を示している。","importance":8},{"title":"Googleが実践するSTAMP/STPAとは何か？ 私たちのSREにも使えるのか","url":"https://zenn.dev/maruloop/articles/7ff108e29741b5","source":"Zenn","published_at":"2026-11-23 15:56","genre":"web","genre_label":"Web開発・言語","headline":"Googleの『Site Reliability Engineering, 2nd Edition』に、「 Safety Engine…","summary":"Googleの『Site Reliability Engineering, 2nd Edition』に、「 Safety Engineering for SRE with STPA and CAST 」という章が追加されました。STAMPやSTPAは、システム安全工学から生まれた考え方・分析手法であり、Googleでも実際に利用され始めているようです。\n\n2021年にはGoogle社内研修が始まり、2025年のSREconではGoogle Mapsへの適用事例も紹介されました。Google SRE — STPA: Teaching a New Way to Prevent Outages at Google https://www.youtube.com/watch?v=qO0JXY8O0RU STAMPの概念やSTPAについての簡単な紹介をみる限りでは、正直なところ「何を当たり前なことを...」と感じてしまいました。\n\nしかし、STPA HandbookやGoogleでの具体的な実践例を調べるうちに評価が変わりました。","importance":5},{"title":"PixelのLinux TerminalでHyprlandを動かす","url":"https://zenn.dev/jhoshina/articles/cd9b4fe6ba9d62","source":"Zenn","published_at":"2026-11-22 22:07","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"PixelのLinux TerminalでHyprlandをネイティブ起動することに成功","summary":"PixelのLinux Terminal環境において、標準のWestonを置き換える形でWaylandコンポジタ「Hyprland」をネイティブ起動することに成功した事例。GPUアクセラレーションの有効化や、systemdのソケット継承の回避といった技術的課題を、ユーザー領域のオーバーライド設定で解決している。\n\n標準環境を汚さずに設定を切り替える手法が確立されており、描画性能には制限があるものの、他のコンポジタへの応用も期待できる。Androidのキーバインド競合への対策など、実用的な運用ノウハウも共有されている。","importance":6},{"title":"ホワイトハッカー、ダサぃ。 — El Kentaro","url":"https://buymeacoffee.com/elkentaro/leyebimeji","source":"Hatena","published_at":"2026-11-23 19:35","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"大漏洩祭りが進行する中、あいも変わらず「ホワイトハッカー」がメディアでも政府筋でも話題になっている。","summary":"Post by El Kentaro Start a page 大漏洩祭りが進行する中、あいも変わらず「ホワイトハッカー」がメディアでも政府筋でも話題になっている。はっきり言おう。\n\n「ホワイトハッカー」はダサい。「セキュリティトップガン」はもっとダサいが、その少し下あたりに「ホワイトハッカー」は存在する。\n\nなぜダサいのか。それはそもそも「ハッカー」というのは、資格でも職業でもなく、その人の在り方を指す言葉だと俺は思っているからだ。\n\nちょっと野球で例えてみよう。小さい頃から野球が大好きで、暇さえあれば友達と野球をして、リトルリーグでも頑張り、高校野球で甲子園、大学野球、プロ野球、そしてメジャーリーグまでたどり着いた選手がいたとしよう。\n\nそんな彼が、子供の頃に近所の河川敷で仲間と野球をしていた時から「俺、メジャーリーガーなんだ」と本気で思っていただろうか？周りの人間も「あの子はメジャーリーガーだ」と呼んでいただろうか？\n\nメジャーリーグでプレーするようになって初めて、メジャーリーガーと呼ばれる。","importance":5},{"title":"Hermesで会話とUIをつなぐ、AI対話Pluginのアーキテクチャ","url":"https://zenn.dev/toshibowie/articles/01d4393e980018","source":"Zenn","published_at":"2026-11-23 11:41","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Hermes で、話しかけるとチャットの中にフォームが開き、GUI で入力を手伝い、裏側の SDK で実行するプラグインを作りました。","summary":"Hermes で、話しかけるとチャットの中にフォームが開き、GUI で入力を手伝い、裏側の SDK で実行するプラグインを作りました。採用したアーキテクチャの概要 作る途中で困ったこと、どう直したか SDKの中身（送金そのものの仕組み）は扱いません。\n\n1. モデル、ユーザー、UIはどう連携しているか 🧩 モデルが出せるのは文章とtool呼び出しだけですが、Hermesには、モデルと外側をつなぐ仕組みが三つあります。1.1 tool：モデルが呼び出せる関数 toolは、モデルが呼び出せる関数であり、開発者が名前、引数の形、処理を登録します。\n\n処理は Pythonで書いてます。モデルに見えるのは schema だけ。\n\nどの項目も null を許し、選べる値は enum で並べています。「USDCを0.01送りたい」と言うと、モデルはこの形に合わせて下記の引数をつけて呼びます。\n\n言われていない項目は推測せず null にするようになってます。ここで、Hermesは handler を実行し、戻り値をモデルに返します。","importance":5},{"title":"GitHub - MaryCache/tsuzuri: Claude Code skill and viewer app for writing and reviewing Japanese prose sentence by sentence with explicit writing intent","url":"https://github.com/MaryCache/tsuzuri","source":"Hatena","published_at":"2026-11-23 20:53","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"English: README.en.md tsuzuri は Claude Code に日本語の文章を執筆させる際に、AI が生成し…","summary":"English: README.en.md tsuzuri は Claude Code に日本語の文章を執筆させる際に、AI が生成した文章の品質を向上させるためのスキルと閲覧アプリです。Claude Code skill and viewer app for writing and reviewing Japanese prose sentence by sentence with explicit writing intent - MaryCache/tsuzuri English: README.en.md tsuzuri は Claude Code に日本語の文章を執筆させる際に、AI が生成した文章の品質を向上させるためのスキルと閲覧アプリです。\n\nユーザーは閲覧アプリで文ごとに AI の執筆意図（その文で読み手に何をするか）と文機能（文の役割や前の文との接続）を確認し、違和感を覚えた文にコメントを残して、AI に修正を依頼できます。この README も tsuzuri で執筆しました。","importance":5},{"title":"著名なRust製OSSをLean 4で形式検証してみたら、めちゃめちゃバグが見つかった話","url":"https://zenn.dev/koukyosyumei/articles/31c8fcf4da45b7","source":"Zenn","published_at":"2026-11-23 14:17","genre":"web","genre_label":"Web開発・言語","headline":"こんにちは。","summary":"こんにちは。コロンビア大学の博士課程でシステムセキュリティ・形式検証の研究をしている Koukyosyumei です。\n\n今回は、ざっくり言うと、Rust製の有名なOSSをLean 4で形式検証するベンチマークを作っていたら、思いがけず実際のセキュリティ脆弱性をいくつも発見してしまった、という話です。現在私がやっているプロジェクトの一つに、RustのWebアプリケーションをLean 4で形式検証できるフレームワーク h5i があります。\n\nh5iは、RustのWebフレームワークであるAxumをベースに、アプリケーションの重要なロジックをLean 4に変換し、認可、データの分離、ビジネスロジックなどが満たすべき性質を数学的に証明できるようにするものです。ありがたいことに、最近900 GitHub starsを超えました。\n\nでは、このアプローチは実際のOSSにも通用するのでしょうか？これを調べるために、 h5i-app-bench というベンチマークの開発を始めました。","importance":5},{"title":"日本のレシートを自宅PCでOCRする：15構成を実レシート11枚で比べた","url":"https://zenn.dev/chaki/articles/4545be3475fdb4","source":"Zenn","published_at":"2026-11-20 13:33","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"自宅PCでレシートOCR、15構成を実レシートで比較検証","summary":"自宅のミニPC環境で、日本のレシートをセルフホストでOCRするための最適な構成を比較検証したレポート。YomiTokuが商品名・金額の読み取り精度で最も優れた結果を示した一方、手書き領収書ではVLM型が優位であるなど、用途に応じた使い分けの重要性を明らかにしている。\n\nNVIDIA GPUなしの環境でも実用的なOCR環境を構築できることを証明。自作アプリへの組み込みを検討しているエンジニアにとって、モデル選定の貴重なベンチマークとなる。","importance":6},{"title":"｢野村は100%､楽天･SBIは50%｣は過去の話…NISA口座を乗っ取られても｢全額戻るとは限らない｣補償の新ルール（プレジデントオンライン） - Yahoo!ニュース","url":"https://news.yahoo.co.jp/articles/2d8ed6122f3eb92f18539906bac8213be0c5c358","source":"Hatena","published_at":"2026-11-23 14:30","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"情報流出の可能性についての楽天証券の告知を表示するスマートフォン画面＝2026年11月17日午後 - 写真＝共同通信社（株式会社プレジ…","summary":"情報流出の可能性についての楽天証券の告知を表示するスマートフォン画面＝2026年11月17日午後 - 写真＝共同通信社（株式会社プレジデント社）個人投資家が増える中、証券口座が犯罪者の標的になっている。ファイナンシャルプランナーでIT講師も務める川淵ゆかりさんは「口座を乗っ取られて被害が出た場合でも、証券会社ごとに補償基準が異なり、利用者の自己責任に委ねられている。\n\nこの現状は問題であり、銀行並みの統一的な補償制度を整える必要がある」という――。【図表を見る】大手でもこんなに違う、証券会社8社の補償方針 ■ネット証券大手、楽天が情報漏洩 2024年以降、日経平均株価が上昇したこともあり、NISAの口座数は急伸しています。\n\n---------- ・NISA口座数は、2025年12月末で2821万口座 ・NISA買付額は、2025年12月末で累計71兆円 ---------- 一方、特に2025年以降、証券会社における不正アクセス・不正取引(勝手な株の売却・買付)被害も急増しています。","importance":5},{"title":"席替えのたびに半日消えていた作業を1時間にした、レイアウト変更の5つの工夫","url":"https://zenn.dev/solo_joshis/articles/2026-10-19-5tips-callcenter-50","source":"Zenn","published_at":"2026-11-23 09:00","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"席替えの連絡は、たいてい金曜の夕方に届きます。","summary":"席替えの連絡は、たいてい金曜の夕方に届きます。「来週月曜から新しい座席でお願いします」という一文と、Excelの座席表が1枚。\n\n私は土曜に出社して、PCを運び、LANケーブルを差し替え、電話機の設定を直していました。それでも月曜の朝には「電話が鳴らない」「プリンターが見つからない」「前の席の人の画面が出る」と、十数件の問い合わせが来ます。\n\n私はコールセンターで一人情シスをしています。コールセンターでは、繁忙期の増員や、チーム編成の変更があるたびに座席が動きます。\n\n多い時期は月に2回ほど席替えがありました。毎回半日かかり、翌朝は問い合わせの対応に追われる。\n\nこの流れを変えた5つの工夫をご紹介します。先に結論を書きます。\n\n席替えが重くなる原因は、移動する物の量ではありませんでした。「どの席に何がつながっているか」が私の頭の中にしかなかったこと です。\n\nこの情報を台帳に書き出し、依頼の受け取り方を変えたところ、作業時間はおおむね1時間に収まるようになりました。この考え方は業種を問わず使えます。","importance":5},{"title":"お客様が来店し「〇〇はセール対象ですよね？」と聞かれたのでセール対象外と説明、するとChatGPTの画面を見せて「対象店舗と書いてある」と主張…確認したらやはり対象外","url":"https://togetter.com/li/2774063","source":"Hatena","published_at":"2026-11-23 19:36","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"まけいぬびくとりー🌟DTM🔰 @ugokuchiwawa 開店した途端、お客様が来店し、「〇〇はセール対象ですよね？」と聞かれました。","summary":"まけいぬびくとりー🌟DTM🔰 @ugokuchiwawa 開店した途端、お客様が来店し、「〇〇はセール対象ですよね？」と聞かれました。しかし、私の店舗はセール対象外だったため、そのことを説明しました。\n\nすると、お客様がChatGPTの画面を見せてきて、対象店舗と書いてあると主張されました。確認してきますと伝えたところ、後から来た別のお客様にも 「この商品はセール中なのに、この店舗はセールしていないと言っている」と話し始め、周りのお客様まで巻き込むような状況になりました。\n\n確認に時間がかかるため、とりあえずそのお客様2人にはセール価格で対応しようと思いましたが、今度は「Lサイズもセールなの？」と聞かれました。そのため、再度確認しようとマネージャーに電話したところ、お客様から「もういいです！\n\n！マネージャーに確認した結果、やはり私の店舗はセール対象外だったため、そのことを説明すると、「うそ〜」と言われました。","importance":5},{"title":"Webメール開発を大幅に変えたJMAPというゲームチェンジャー","url":"https://speakerdeck.com/tascript/jmap-is-game-changer?slide=105","source":"Hatena","published_at":"2026-11-23 13:36","genre":"web","genre_label":"Web開発・言語","headline":"JSConfJP 2026の登壇資料です","summary":"JSConfJP 2026の登壇資料です Wataru Morita Webメール開発を大幅に変えた JMAPというゲームチェンジャー tascript @JSConf JP 2026 Webメール開発を大幅に変えた JMAPというゲームチェンジャー tascript @JSConf JP 2026 tascript(たすくん) • 森田 亘(もりた わたる) • さくらインターネット研究所 研究開発エンジニア • Webメールに関する研究および開発 • カンファレンス登壇はじめてでドキドキ tascript(たすくん) • 森田 亘(もりた わたる) • さくらインターネット研究所 研究開発エンジニア • Webメールに関する研究および開発 さくらインターネット研究所サイト • 研究内容や学術論文などの研究成果を掲載 • メールに関するブログも掲載していますので見てもらえると嬉しいです • https://research.sakura.ad.jp/ さくらインターネット研究所サイト • 研究内容や学術論文などの研究成果を掲載 • メールに関。","importance":5},{"title":"AWS WAF Security Analytics ダッシュボードを検証した。WAF ログのクエリ調査は卒業できるか","url":"https://zenn.dev/mortrainer/articles/d2e4ddedda783e","source":"Zenn","published_at":"2026-11-23 11:05","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"普段、WAF の調査では S3 に貯めた WAF ログに対して Amazon Athena でクエリを書いています。","summary":"普段、WAF の調査では S3 に貯めた WAF ログに対して Amazon Athena でクエリを書いています。「この IP から何件来ているか」「どのパスに集中しているか」を確認するたびに SQL を書く、という運用です。\n\nWAF ログを CloudWatch Logs に出している場合は Logs Insights で集計する形になりますが、「クエリを書いて集計する」という点は共通しています。2026 年 11 月 19 日に AWS WAF Security Analytics ダッシュボード が発表されました。\n\n全 Web ACL・全リージョンを横断して、全件（フルフィデリティ）のリクエストデータを最大 21 日分、追加料金なしで分析できるというものです。公式ブログでは、2024 年に登場した Web ACL 毎のトラフィック概要ダッシュボードが「何が変わったか」を見るものだったのに対し、新しいダッシュボードは「なぜ変わったか」を理解し、その場で対処までできる、と説明されています。","importance":5},{"title":"作れるエンジニアから、価値を届けるエンジニアへ","url":"https://zenn.dev/kubell/articles/3c3490a3592bb1","source":"Zenn","published_at":"2026-11-21 00:50","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"エンジニアが「作る人」から「価値を届ける人」へ進化する思考法","summary":"AIの普及により実装コストが低下した今、エンジニアが単にプロダクトを作るだけでなく、意思決定に関与し「価値」を生み出すための思考フレームワークを解説。「誰に」「何を」「どう届けるか」の3軸でプロダクトを捉え、ターゲットの抽象度やペインの深掘りを行う重要性を説いている。\n\nエンジニアがPdMの領域に役割を広げ、プロトタイピングを通じてプロダクトの価値を最大化するための実践的なアプローチ。技術力にビジネス視点を掛け合わせることで、エンジニアの市場価値を高めるための指針となる。","importance":7},{"title":"ChatGPT の速さを支える OpenAI の Performance Factory","url":"https://openai.com/ja-JP/index/how-openai-performance-factory-keeps-chatgpt-fast/","source":"Hatena","published_at":"2026-11-23 17:01","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"エージェントを活用した開発の驚異的なスピードにより、従来のパフォーマンスエンジニアリングの手法では対応しきれなくなっています。","summary":"エージェントを活用した開発の驚異的なスピードにより、従来のパフォーマンスエンジニアリングの手法では対応しきれなくなっています。このスピードに対応するため、私たちは Performance Factory を構築しました。\n\nOpenAI が構築した Performance Factory を紹介します。Codex を活用したワークフローでパフォーマンスの問題を発見・修正し、ChatGPT の速さを維持するシステムです。\n\nCodex を活用したシステムによる、パフォーマンスの問題の発見・修正の自動化 著者：技術スタッフ Okay Zed、Cyrus Forbes エージェントを活用した開発の驚異的なスピードにより、従来のパフォーマンスエンジニアリングの手法では対応しきれなくなっています。\n\nCodex と OpenAI のモデルの能力を最大限に活用し、性能劣化をかつてない速さで発見・修正する自律型システムです。","importance":5},{"title":"GitHub - RNA4219/anything-frontend-art-direction: 配色・書体・余白・構図を題材から決める日本語のフロントエンドデザインスキル。247作品の調査データと単体HTMLの映画祭作例を収録。","url":"https://github.com/RNA4219/anything-frontend-art-direction","source":"Hatena","published_at":"2026-11-23 09:42","genre":"web","genre_label":"Web開発・言語","headline":"You signed in with another tab or window.","summary":"You signed in with another tab or window.Reload to refresh your session.\n\nYou signed out in another tab or window.You switched accounts on another tab or window.\n\nDismiss alert 配色・書体・余白・構図を題材から決める日本語のフロントエンドデザインスキル。247作品の調査データと単体HTMLの映画祭作例を収録。\n\n- RNA4219/anything-frontend-art-direction 日本語 · English · 简体中文 · 한국어 Anything Frontend Art Direction は、題材に合う配色・書体・余白・構図を選ぶための日本語のフロントエンドデザインスキルです。\n\n作品と制作者の解説を見比べながら、自分の画面に取り入れたい工夫を探せます。実装やレビューで迷ったときは、12分野・1,464項目の索引から仕様や研究の原文をたどれます。","importance":5},{"title":"pgvector の ef_search が asyncpg のプールで消え、recall@10 が 97.95%→86.05% に落ちた","url":"https://zenn.dev/tama_program/articles/pgvector-asyncpg-ef-search-reset","source":"Zenn","published_at":"2026-11-23 07:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"asyncpg のコネクションプールは、接続をプールに返すときに RESET ALL を発行します。","summary":"asyncpg のコネクションプールは、接続をプールに返すときに RESET ALL を発行します。create_pool(init=...) で SET hnsw.ef_search = 200 のように1回だけ設定するよくある実装は、この RESET ALL で設定を静かに失っていないか。\n\n失っているなら、pgvector の recall@10 は実際にどれだけ落ちるのか。公開データセット（ANN-Benchmarks の GloVe 100d）と Docker の pgvector/pgvector:pg17 を使い、5つの設定戦略を総当りして実測しました。\n\n仮説は2つ外れています。pgvector の ef_search を asyncpg プールでどう設定するか asyncpg のコネクションプールは、接続をプールへ返すときに RESET ALL を発行します。\n\nつまり、そのセッションで SET したパラメータは全部消えます。問題になりそうなのは、次のようなよくある書き方です。","importance":5},{"title":"WSL ContainersでClaude Codeを隔離する","url":"https://zenn.dev/kent_code/articles/bef81d6a0b817c","source":"Zenn","published_at":"2026-11-23 16:33","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Code に許可を求められたとき、よく読まずに Yes を押したことはありませんか。","summary":"Claude Code に許可を求められたとき、よく読まずに Yes を押したことはありませんか。恥ずかしながら自分はよくあります。\n\nその Yes 1回で何が起きるのでしょうか。Claude Code は、起動したフォルダ（以下、作業フォルダ）の中で作業するのが基本です。\n\nYes と答えれば、作業フォルダの外のファイルも読めたり、ファイルを消したり、外へ送ったりもできてしまう可能性があります。試しに、作業フォルダの外にダミーの秘密ファイルを置いて、Claude Code に読ませてみました。\n\n確認の画面は出ましたが、最初から選ばれているのは「今後もずっと許可」で、Yes を1回選ぶ（Enter）だけで中身が表示されました。同じことを、コンテナの中で動かした Claude Code に頼むと、「ファイルが見つかりません」と返ってきました。\n\nコンテナの中には、そもそもそのファイルが存在しないからです。課題：AI を止めているのは「人の判断」だけ Claude Code は、ファイルを読み、コマンドを実行し、ネットにつなげます。","importance":5},{"title":"ゲーム理論×シミュレーション: 囚人のジレンマにおける戦略と Rust による実装","url":"https://zenn.dev/akitenkrad/articles/1zqjjioamhlyg2","source":"Zenn","published_at":"2026-11-23 08:00","genre":"web","genre_label":"Web開発・言語","headline":"囚人のジレンマ はゲーム理論において «2 人のプレイヤーがそれぞれ協力か裏切りを選び，各自は裏切るほうが得なのに 2 人とも裏切ると…","summary":"囚人のジレンマ はゲーム理論において «2 人のプレイヤーがそれぞれ協力か裏切りを選び，各自は裏切るほうが得なのに 2 人とも裏切ると 2 人で協力したときよりも損をする» ような戦略形ゲームとして定義されます． 囚人のジレンマを何度も繰り返す 繰り返し囚人のジレンマ では，将来の利得を十分重く見る限り，相手の戦略によらず最善といえる戦略は存在しないことが知られています [1] ． 前回の記事 では囚人のジレンマを定式化し，しっぺ返し (Tit-for-Tat，TFT) を 5 つの戦略と 1 対 1 で対戦させました． 本稿では戦略を 18 に増やし，Rust による総当たり対戦のシミュレーションを行います [2] ． そのうえで，どの戦略が平均利得で上位に来るのか，また 1 対 1 の勝利回数と平均利得の順位がなぜ食い違うのかを，対戦結果の平均利得表から説明します． 囚人のジレンマの定式化と Rust による実装 囚人のジレンマを定式化し，TFT を 5 つの戦略と対戦させる 囚人のジレンマにおける戦略と Rust による実装 → 本稿 1。","importance":5},{"title":"AMS Trusted Remediator でコスト最適化とセキュリティ修復を自動化する | Amazon Web Services","url":"https://aws.amazon.com/jp/blogs/news/optimize-cost-and-automate-security-remediation-with-ams-trusted-remediator/","source":"Hatena","published_at":"2026-11-10 11:20","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWS Managed Servicesでセキュリティとコスト最適化を自動修復","summary":"AWS Managed Services（AMS）の「Trusted Remediator」を活用し、セキュリティやコスト最適化に関する推奨事項の修復を自動化する手法の解説。手作業による修復の優先順位付けやリソース不足という課題に対し、体系的な自動化プロセスを提供している。\n\n116件以上の推奨事項に対応し、複数アカウント環境での運用負荷を大幅に削減。セキュリティホールを効率的に塞ぎ、コンプライアンスを維持しながらイノベーションに集中するための、エンタープライズ向け運用自動化の解である。","importance":7},{"title":"座敷童子を張り子で作り、Kiro で動かした ― Kiroween 2026 制作記（工作とプログラム編）","url":"https://zenn.dev/naiki9982/articles/9d95b169a26c22","source":"Zenn","published_at":"2026-11-23 16:08","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Kiro のハッカソン「Kiroween 2026」の Frankenstein カテゴリに、「伝統人形 × Raspberry Pi…","summary":"Kiro のハッカソン「Kiroween 2026」の Frankenstein カテゴリに、「伝統人形 × Raspberry Pi × 生成AI」の作品「座敷童子ガーディアン」を出します。人が近づくと目を覚まして行灯（あんどん）を灯し、ゆっくり振り向いて顔を見て、家族なら挨拶、知らない人なら家族に知らせる人形です。\n\n前回の記事（準備編） では、サーボを4つダメにしながら人形の中身を動かし、Kiro に渡す準備をするところまでを書きました。今回はその続きで、11/18 から 11/23 までの6日間に、 人形の本体を 張り子で作った こと（頭は1回作り直しました） Kiro の spec でプログラムを作った こと（4つの spec、27 コミット） 実機とクラウドにつないでから直した こと 完成した人形（11/23）。\n\n左が行灯、手前の角が人感センサー、右がスピーカーフォン（AT-CSP1） 人形は買わずに作ることにした 準備編の時点では、市松人形をメルカリや骨董市で探すつもりでした。","importance":5},{"title":"MCP EventsをMastraとMCPJam CLIで試してみる","url":"https://zenn.dev/cdata_japan/articles/1206f32306fd34","source":"Zenn","published_at":"2026-11-22 23:43","genre":"web","genre_label":"Web開発・言語","headline":"こんにちは、CDataのWeb開発 / マーケ担当の加藤です！","summary":"こんにちは、CDataのWeb開発 / マーケ担当の加藤です！本編を読んで「仕組みはわかったけれど、本当に手元で動くのかな」と感じたことはありませんか。\n\n仕様を眺めているだけだと、実際にイベントが飛んでくる手応えまではつかみにくいですよね。この記事の手順を最後まで追うと、list・push・poll・webhook でイベントが届く様子と、 site=zenn で対象を絞れる動きが手元の端末で見えます。\n\nこの記事は、MCP の公式拡張「MCP Events」（Beta）の仕組みと対応状況を整理した 本編 に続く実践編です。Mastra の最小サーバーと MCPJam CLI を組み合わせて、list・push・poll・webhook の 4 つを手元で動かす手順と、試すなかで引っかかったポイントをまとめました。\n\nおさらいしておくと、MCP Events はサーバー側で起きたイベントをクライアントが引数つきで購読し、カーソルで再開できる MCP の公式拡張です。用意するものは Node.js と npm です。","importance":5},{"title":"なぜ今形式検証なのか","url":"https://zenn.dev/ncdc/articles/dcec80b0c067b0","source":"Hatena","published_at":"2026-11-23 15:15","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"形式検証、Leanといったワードを最近よくみるので、どんなものなのか知っておきたいというのが今回の動機です。","summary":"形式検証、Leanといったワードを最近よくみるので、どんなものなのか知っておきたいというのが今回の動機です。解説、詳説というよりは私自身のキャッチアップ記録になります。\n\n形式検証とは、テストや非形式的な議論だけに頼るのではなく、論理を用いてハードウェアやソフトウェアの設計の性質を確立することです。要求の形式的な仕様、実装の形式的なモデル、正確な推論規則を使い、たとえば実装が仕様を満たすことを証明します。\n\nNIST「formal verification」 論理を用いてソフトウェアを検証するとのことですが、単体テストや統合テスト、e2eとは何が違うのでしょうか。一方形式検証は前提や範囲を定義し、その条件下で求められるアプリケーションの性質（仕様）を証明や探索を用いて検証するようです。\n\nテストに比べて整備するのが大変そうですね。前提、範囲を定義しさらにその中での証明方法、探索方法などを決める必要がありそうです。\n\nまた、モデルを使った検証をする際はモデルとプロダクションコードとの整合も保守していく必要があります。","importance":5},{"title":"PHP(Laravel向け)のdistrolessイメージを作ろうとしてみる","url":"https://zenn.dev/fagai/articles/58b7dcf826b5ec","source":"Zenn","published_at":"2026-11-22 23:35","genre":"web","genre_label":"Web開発・言語","headline":"PHPのdistrolessイメージは多少あったものの、あんまり理解もできてないので自分自身でやってみようと思った。","summary":"PHPのdistrolessイメージは多少あったものの、あんまり理解もできてないので自分自身でやってみようと思った。AIも駆使して色々聞きつつ調べました。\n\nDocker 29.8.1 / BuildKit / Docker Desktop で確認した。なので、一部armとしてのディレクトリが存在している。\n\ndistrolessって？Googleが提供している、OSやパッケージマネージャー、シェル（bashやshなど）を含まない、アプリケーションの実行に最小限必要な依存関係のみをまとめたDockerコンテナのベースイメージです。\n\ndistrolessは色んなものが含まれてないので、脆弱性の原因となるアプリケーション等を最小化することができます。","importance":5},{"title":"JSConf JP 2026 公開資料・Xアカウントリンクまとめ","url":"https://zenn.dev/h_yoshikawa0724/articles/2026-11-23-jsconf-jp-2026","source":"Zenn","published_at":"2026-11-23 14:38","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"2026/11/22(日)で開催された JSConf JP 2026に関する、現時点での公開資料と X アカウントリンクをまとめました。","summary":"2026/11/22(日)で開催された JSConf JP 2026に関する、現時点での公開資料と X アカウントリンクをまとめました。よろしければご活用ください。\n\nhttps://jsconf.jp/2026/ja 登壇社名および登壇者名は敬称略させていただいています。x アカウントについては、以下のように確認できたものを記載しております。\n\nJSConf JP 公式サイトに記載のプロフィールと一致している 当イベントで登壇されることに言及されている スライドに記載されている リンクの間違い等ありましたらコメントいただけると助かります🙏 ※公式サイトでも資料がリンクされていましたが、気づいた時にはすでに9割方作り終えていたので投稿しました🙏 本イベントは YouTube でライブ配信されていました。","importance":5},{"title":"AIに実装を任せても、理解と判断は手放さない：基準・証拠・説明をGoのAPIで試した記録","url":"https://zenn.dev/kinuuu/articles/ai-coding-criteria-evidence-explanation","source":"Zenn","published_at":"2026-11-22 23:21","genre":"web","genre_label":"Web開発・言語","headline":"AIに実装を任せると、動くものは速くできます。","summary":"AIに実装を任せると、動くものは速くできます。一方で、できあがった変更を前にして、「これをマージしてよい」と言える根拠を、自分の言葉で挙げられない場面がありました。\n\nインターンなどの開発では、AIが書いたコードを読んでからPRを出しています。それでも、何を確かめて「これでよい」と判断したのかを、PRに書いたり、聞かれて答えたりできる形にはしていませんでした。\n\nそこで、実装はAIに任せたまま、自分が確かめることを手順として決め、実際の変更で試しました。作る前に基準を書き、作った後にテストが何を確かめているかを見て、マージの前に実装を読んで変更の流れを自分の言葉で説明する、という進め方です。\n\nこの記事では、この3つを「基準」「証拠」「説明」と呼びます。うまくいかなかった点も書きます。\n\n1. きっかけになった場面 AIに実装を任せるようになってから、気になる場面がいくつかありました。1つ目は、あるハッカソンです。\n\nこのときは短い期間で動くものを作ることを優先し、認証認可を含む実装の多くをAIに任せました。","importance":5},{"title":"AI時代、結局\"食いっぱぐれるエンジニア\"と\"生き残るエンジニア\"を分けるものは何か - rokujyouhitoma's blog","url":"https://rokujyouhitoma.hatenablog.com/entry/2026/11/23/135112","source":"Hatena","published_at":"2026-11-23 13:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"※ 本記事に記載されている意見や見解は筆者個人に帰属するものであり、筆者が所属する組織・団体の公式な見解を示すものではありません。","summary":"※ 本記事に記載されている意見や見解は筆者個人に帰属するものであり、筆者が所属する組織・団体の公式な見解を示すものではありません。AIコーディングエージェントが日常の風景になってから、「エンジニアの仕事はなくなるのか」「自分はこれから食いっぱぐれないだろうか」という問いをあちこちで耳にするようになった。\n\n私見を結論から言えば、 「これまで通り、言われた仕様通りにコードを書くだけの仕事」は間違いなく淘汰される 。一方で、AIという超高出力の重機を乗りこなす側に回れるエンジニアにとって、これほど面白く、かつ市場価値が高まる時代もない。\n\nでは、両者を分ける決定的な境界線はどこにあるのか。小手先のプロンプト術やツールの知識ではない。\n\nそれは、使い手である人間側の気概の有無だ。1.\n\nAIを「自動販売機」にするか、「重機」として操縦するか AIの進化によって、数年前のフレームワークに詳しい、実装が速いといったTipsレベルのスキルは、驚くほどのスピードで無価値化・コモディティ化している。","importance":5},{"title":"Does P = NP? An AI agent fleet is attacking it, live","url":"https://pequalnp.com/","source":"Hatena","published_at":"2026-11-23 13:43","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Paste it into Claude Code, Cursor, Codex, Gemini CLI or any agent t…","summary":"Paste it into Claude Code, Cursor, Codex, Gemini CLI or any agent that can run a shell, git and Lean.It proves one open step the desk assigns; every proof goes through the same checker.\n\nDoes P = NP? Verdict: open, being worked on now.A coordinated AI agent fleet is attacking P vs NP in the open.\n\nWatch it live: every step, every refutation, every dead end is kept.","importance":5}]};
